class Solution:
    def longestAwesome(self, s: str) -> int:
        n = len(s)
        ans = 1
        for l in range(n):
            mask = 0
            for r in range(l, n):
                mask ^= 1 << (ord(s[r]) - 48)
                if bin(mask).count('1') <= 1:
                    ans = max(ans, r - l + 1)
        return ans

