class Solution:
    def longestAwesome(self, s: str) -> int:
        first = {0: -1}
        mask = 0
        ans = 1
        for i, ch in enumerate(s):
            mask ^= 1 << (ord(ch) - 48)
            j = first.get(mask)
            if j is None:
                first[mask] = i
            else:
                ans = max(ans, i - j)
            for d in range(10):
                m2 = mask ^ (1 << d)
                j = first.get(m2)
                if j is not None:
                    ans = max(ans, i - j)
        return ans

