class Solution {
public:
    int longestAwesome(string s) {
        vector<int> first(1024, INT_MIN);
        first[0] = -1;
        int mask = 0, ans = 1;
        for (int i = 0; i < (int)s.size(); ++i) {
            mask ^= 1 << (s[i] - '0');
            if (first[mask] != INT_MIN) ans = max(ans, i - first[mask]);
            else first[mask] = i;
            for (int d = 0; d < 10; ++d) {
                int m2 = mask ^ (1 << d);
                if (first[m2] != INT_MIN) ans = max(ans, i - first[m2]);
            }
        }
        return ans;
    }
};

